// PlanServiceHandler is an implementation of the harpia.plans.v1.PlanService service.
type PlanServiceHandler interface {
	// Template catalog (global, read-only for tenants).
	GetPlanTemplate(context.Context, *connect.Request[v1.GetPlanTemplateRequest]) (*connect.Response[v1.GetPlanTemplateResponse], error)
	GetPlanTemplateByKey(context.Context, *connect.Request[v1.GetPlanTemplateByKeyRequest]) (*connect.Response[v1.GetPlanTemplateByKeyResponse], error)
	ListPlanTemplates(context.Context, *connect.Request[v1.ListPlanTemplatesRequest], *connect.ServerStream[v1.ListPlanTemplatesResponse]) error
	// Tenant plan configuration lifecycle.
	CreatePlanConfiguration(context.Context, *connect.Request[v1.CreatePlanConfigurationRequest]) (*connect.Response[v1.CreatePlanConfigurationResponse], error)
	GetPlanConfiguration(context.Context, *connect.Request[v1.GetPlanConfigurationRequest]) (*connect.Response[v1.GetPlanConfigurationResponse], error)
	UpdatePlanConfiguration(context.Context, *connect.Request[v1.UpdatePlanConfigurationRequest]) (*connect.Response[v1.UpdatePlanConfigurationResponse], error)
	ListPlanConfigurations(context.Context, *connect.Request[v1.ListPlanConfigurationsRequest], *connect.ServerStream[v1.ListPlanConfigurationsResponse]) error
	// Conversational configuration assistant: derive and append the next
	// ASSISTANT_PROMPT for a configuration (binding/overseer/policies/matrix).
	NextTurn(context.Context, *connect.Request[v1.NextTurnRequest]) (*connect.Response[v1.NextTurnResponse], error)
	// Submit a user's selection for the current ASSISTANT_PROMPT. The server
	// infers the mutation kind from the prompt's payload and applies it
	// atomically, then returns the updated configuration plus the messages
	// appended this turn (USER_SELECTION, optional STEP_REBOUND, next
	// ASSISTANT_PROMPT). Replaces the browser's 4-RPC configuration-selection
	// orchestration with a single server-authoritative call.
	SubmitConfigurationSelection(context.Context, *connect.Request[v1.SubmitConfigurationSelectionRequest]) (*connect.Response[v1.SubmitConfigurationSelectionResponse], error)
	// Execution (MVP stubs — messages defined for downstream workflow wiring).
	CreatePlanExecution(context.Context, *connect.Request[v1.CreatePlanExecutionRequest]) (*connect.Response[v1.CreatePlanExecutionResponse], error)
	RetryPlanExecution(context.Context, *connect.Request[v1.RetryPlanExecutionRequest]) (*connect.Response[v1.RetryPlanExecutionResponse], error)
	GetPlanExecution(context.Context, *connect.Request[v1.GetPlanExecutionRequest]) (*connect.Response[v1.GetPlanExecutionResponse], error)
	ListPlanExecutions(context.Context, *connect.Request[v1.ListPlanExecutionsRequest], *connect.ServerStream[v1.ListPlanExecutionsResponse]) error
	GetStepExecution(context.Context, *connect.Request[v1.GetStepExecutionRequest]) (*connect.Response[v1.GetStepExecutionResponse], error)
	ListStepExecutions(context.Context, *connect.Request[v1.ListStepExecutionsRequest], *connect.ServerStream[v1.ListStepExecutionsResponse]) error
	// In-app elicitation thread (E5.1, FR-11, UX-DR5).
	// Overseers receive and answer agent questions scoped to a StepExecution.
	ListElicitations(context.Context, *connect.Request[v1.ListElicitationsRequest]) (*connect.Response[v1.ListElicitationsResponse], error)
	GetElicitation(context.Context, *connect.Request[v1.GetElicitationRequest]) (*connect.Response[v1.GetElicitationResponse], error)
	RespondToElicitation(context.Context, *connect.Request[v1.RespondToElicitationRequest]) (*connect.Response[v1.RespondToElicitationResponse], error)
	WatchElicitations(context.Context, *connect.Request[v1.WatchElicitationsRequest], *connect.ServerStream[v1.WatchElicitationsResponse]) error
	// Candidate review/revision is distinct from elicitation and approval.
	ListReviewRequests(context.Context, *connect.Request[v1.ListReviewRequestsRequest]) (*connect.Response[v1.ListReviewRequestsResponse], error)
	GetReviewRequest(context.Context, *connect.Request[v1.GetReviewRequestRequest]) (*connect.Response[v1.GetReviewRequestResponse], error)
	RespondToReviewRequest(context.Context, *connect.Request[v1.RespondToReviewRequestRequest]) (*connect.Response[v1.RespondToReviewRequestResponse], error)
	WatchReviewRequests(context.Context, *connect.Request[v1.WatchReviewRequestsRequest], *connect.ServerStream[v1.WatchReviewRequestsResponse]) error
	// Publish approval gate (E5.2, FR-13, UX-DR6).
	// Overseers approve or reject LinkedInPostDraft artifacts before publish steps run.
	ListApprovalRequests(context.Context, *connect.Request[v1.ListApprovalRequestsRequest]) (*connect.Response[v1.ListApprovalRequestsResponse], error)
	GetApprovalRequest(context.Context, *connect.Request[v1.GetApprovalRequestRequest]) (*connect.Response[v1.GetApprovalRequestResponse], error)
	RespondToApprovalRequest(context.Context, *connect.Request[v1.RespondToApprovalRequestRequest]) (*connect.Response[v1.RespondToApprovalRequestResponse], error)
	WatchApprovalRequests(context.Context, *connect.Request[v1.WatchApprovalRequestsRequest], *connect.ServerStream[v1.WatchApprovalRequestsResponse]) error
}

